(()=>{
 'use strict';const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fa=n=>Number(n).toLocaleString('fa-IR',{maximumFractionDigits:4});
 const input=(name,label,value='',type='text',extra='')=>'<label class="form-control"><span>'+label+'</span><input class="input" name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></label>';
 const checks=(confirmation)=>input('reason','دلیل تغییر','','text','required minlength="5" maxlength="500"')+input('confirmation','برای تأیید بنویس: '+esc(confirmation),'','text','required autocomplete="off"')+'<button class="btn btn-primary" type="submit">'+window.RI.icon('check')+'ثبت تغییر</button><p role="status"></p>';
 window.ownerUserControls=(d)=>{
  const u=d.user,confirmation=u.phone||u.id,active=d.access.filter(x=>x.ref.startsWith('subscription:')&&Number(x.expires_at)>Date.now()).sort((a,b)=>Number(b.expires_at)-Number(a.expires_at))[0];
  const limit=Object.hasOwn(d.ownerSettings||{},'subdomainLimit')?d.ownerSettings.subdomainLimit:(active?2:1)+(d.ownerSettings?.extraSubdomain?1:0),documents=d.documents||(d.document?[d.document]:[]),used=documents.filter(x=>x.slug&&x.slot!==3&&(limit===null||((x.slot||1)<3?(x.slot||1):x.slot-1)<=limit)).length,locked=documents.filter(x=>x.slug&&x.slot!==3&&limit!==null&&((x.slot||1)<3?(x.slot||1):x.slot-1)>limit).length;
  const form=(id,body)=>'<form class="owner-control-form" data-owner-operation="'+id+'" data-user="'+u.id+'" '+(id!=='subscription'?'hidden':'')+'>'+body+checks(confirmation)+'</form>';
  return '<section class="owner-workspace"><h2>'+window.RI.icon('shield')+'کنترل پیشرفتهٔ مالک</h2><p>دسترسی حساس به همین حساب؛ هر تغییر با دلیل و تأیید دقیق ثبت می‌شود.</p><div class="tabs" role="tablist" aria-label="کنترل پیشرفته مالک">'+[['subscription','اشتراک و زمان'],['password','امنیت و رمز'],['profile','مشخصات کامل'],['access','دسترسی محصولات'],['wallet','اصلاح اعتبار'],['page-quota','سهمیهٔ صفحه']].map(([id,label])=>'<button type="button" class="tab" role="tab" data-owner-tab="'+id+'" aria-selected="'+(id==='subscription')+'">'+label+'</button>').join('')+'</div>'+
  form('subscription','<p>این تغییر، اشتراک فعال قبلی را جایگزین می‌کند؛ پرداخت بانکی یا خرید جعلی ثبت نمی‌شود.</p><label>نوع اشتراک<select class="select" name="plan">'+[['none','بدون اشتراک'],['q','رخش · سه‌ماهه'],['h','سیمرغ · شش‌ماهه'],['y','هما · سالانه']].map(([id,label])=>'<option value="'+id+'" '+((active?.ref.split(':')[1]||'none')===id?'selected':'')+'>'+label+'</option>').join('')+'</select></label>'+input('days','روزهای باقی‌مانده از امروز',active?Math.max(1,Math.ceil((active.expires_at-Date.now())/86400000)):90,'number','required min="0" max="3650" step="1"'))+
  form('password','<p class="notice">رمز قبلی قابل نمایش نیست. تعیین رمز تازه تمام نشست‌های کاربر و کدهای بازیابی فعلی را باطل می‌کند.</p>'+input('password','رمز تازه (حداقل ۱۲ کاراکتر، حروف بزرگ و کوچک انگلیسی و عدد)','','password','required minlength="12" maxlength="128" autocomplete="new-password"')+'<label class="check"><input class="checkbox" type="checkbox" name="show-password">نمایش رمز تازه</label>')+
  form('profile',input('first_name','نام',u.first_name,'text','required maxlength="39"')+input('last_name','نام خانوادگی',u.last_name,'text','required maxlength="39"')+input('role','عنوان حرفه‌ای',u.role,'text','maxlength="100"')+'<label>معرفی<textarea class="textarea" name="bio" maxlength="500">'+esc(u.bio)+'</textarea></label><p>شمارهٔ تأییدشده از این فرم تغییر نمی‌کند؛ انتقال شماره به تأیید هویت واقعی نیاز دارد.</p>')+
  form('access','<div class="owner-product-picker"><label>جست‌وجوی محصول<input class="input" type="search" data-owner-access-search placeholder="نام یا شناسهٔ محصول"></label><div role="tablist" aria-label="نوع محصول">'+[['','همه'],['rt','رزومه'],['lt','لینک'],['font','فونت'],['pal','رنگ']].map(([key,label])=>'<button type="button" role="tab" data-access-kind="'+key+'" aria-selected="'+(key==='')+'">'+label+'</button>').join('')+'</div><label>محصول<select class="select" name="ref" size="6" required data-owner-products><option value="rt:vista">قالب ویستا</option></select></label><small data-product-selection>محصولی انتخاب کن؛ نام و شناسهٔ آن اینجا نمایش داده می‌شود.</small></div><label>دسترسی<select class="select" name="enabled"><option value="true">اعطای دائمی</option><option value="false">لغو دسترسی خریداری‌شده</option></select></label><p>اشتراک ممکن است همچنان دسترسی به محصول را بدهد. این عملیات سابقهٔ پرداخت را تغییر نمی‌دهد.</p>')+
  form('wallet','<p>موجودی ثبت‌شده: '+fa(Number(d.balance_units)/2000)+' It. اصلاح اعتبار یک تراکنش مستقل ثبت می‌کند؛ سابقهٔ بانکی دست‌کاری نمی‌شود و موجودی منفی مجاز نیست.</p>'+input('delta','مقدار تغییر به It؛ مثبت برای افزایش و منفی برای کسر',0,'number','required min="-50000" max="50000" step="0.0005"'))+
  form('page-quota','<dl class="quota-summary">'+[['سقف ریزدامنه',limit===null?'نامحدود':fa(limit)],['آدرس فعال تخصیص‌یافته',fa(used)],['باقی‌مانده',limit===null?'نامحدود':fa(Math.max(0,limit-used))],['آدرس خارج از سهمیه',fa(locked)]].map(([label,value])=>'<div><dt>'+label+'</dt><dd>'+value+'</dd></div>').join('')+'</dl><label class="check"><input type="checkbox" class="checkbox" name="unlimited" '+(limit===null?'checked':'')+'>سهمیهٔ نامحدود ریزدامنه</label><label>سقف تعیین‌شدهٔ مالک<div class="quota-stepper"><button type="button" class="btn" data-quota-step="-1" title="کاهش یک ریزدامنه" aria-label="کاهش یک ریزدامنه">−</button><input class="input" name="limit" type="number" min="1" max="100000" step="1" required value="'+(limit??Math.max(1,used))+'" '+(limit===null?'disabled':'')+'><button type="button" class="btn" data-quota-step="1" title="افزایش یک ریزدامنه" aria-label="افزایش یک ریزدامنه">'+window.RI.icon('plus')+'</button></div></label><p>این سقف مستقل از نوع اشتراک است. آدرس مسیری فقط با اشتراک فعال جداگانه در دسترس است. کاهش سهمیه داده‌ها را حذف نمی‌کند؛ آدرس‌های بالاتر از سقف از نمایش عمومی خارج می‌شوند.</p>')+'</section>';
 };
 window.ownerCommerceControls=d=>{window.ownerCommerceSnapshot=d.policy;return '<section class="owner-workspace"><h2>'+window.RI.icon('settings')+'نرخ It و محدودیت تصاویر</h2><p>نرخ سراسری فقط شارژهای جدید را تغییر می‌دهد؛ موجودی قبلی، قیمت It محصولات و پیش‌فاکتورهای قبلی حفظ می‌شوند.</p><form id="owner-commerce-form">'+input('rate','تومان برای هر It جدید',d.policy.rate,'number','required min="100" max="10000000" step="1"')+input('imagePaid','سقف عکس اشتراکی، کیلوبایت',d.policy.imagePaid/1024,'number','required min="5" max="2048" step="1"')+input('imageFree','سقف عکس رایگان، کیلوبایت (حداکثر یک‌پنجم)',d.policy.imageFree/1024,'number','required min="1" max="409" step="1"')+checks('تغییر تنظیمات فروش')+'</form></section>';};
 window.bindOwnerControls=(api,reload,ownerId)=>{
  document.addEventListener('click',e=>{const button=e.target.closest('[data-quota-step]');if(!button)return;const input=button.closest('form').elements.limit;if(input.disabled)return;input.value=String(Math.max(1,Math.min(100000,Number(input.value||1)+Number(button.dataset.quotaStep))));});
  document.addEventListener('change',e=>{if(e.target.name==='unlimited')e.target.closest('form').elements.limit.disabled=e.target.checked;});
  function productOptions(root){const select=root.querySelector('[data-owner-products]');if(!select?._products)return;const selected=select.value,q=root.querySelector('[data-owner-access-search]').value.trim().toLocaleLowerCase('fa'),kind=root.querySelector('[data-access-kind][aria-selected=true]')?.dataset.accessKind||'';const items=select._products.filter(x=>(!kind||x.ref.startsWith(kind+':'))&&(!q||(x.name+' '+x.ref+' '+(x.admin_code||'')).toLocaleLowerCase('fa').includes(q)));select.innerHTML=items.map(x=>'<option value="'+esc(x.ref)+'">'+esc(x.name)+' · '+esc(x.admin_code||x.ref)+'</option>').join('');if(items.some(x=>x.ref===selected))select.value=selected;else select.selectedIndex=-1;const item=select._products.find(x=>x.ref===select.value);root.querySelector('[data-product-selection]').textContent=item?item.name+' · '+(item.admin_code||item.ref):items.length+' نتیجه؛ یک محصول انتخاب کن';}
  document.addEventListener('click',e=>{const button=e.target.closest('[data-access-kind]');if(!button)return;const root=button.closest('.owner-product-picker');root.querySelectorAll('[data-access-kind]').forEach(b=>b.setAttribute('aria-selected',String(b===button)));productOptions(root);});
  document.addEventListener('keydown',e=>{const tab=e.target.closest('[data-owner-tab]');if(!tab||!['Home','End','ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const tabs=[...tab.parentElement.querySelectorAll('[data-owner-tab]')],index=tabs.indexOf(tab),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowLeft'?1:-1)+tabs.length)%tabs.length;tabs[next].click();tabs[next].focus();});
  document.addEventListener('click',e=>{const tab=e.target.closest('[data-owner-tab]');if(!tab)return;const root=tab.closest('.owner-workspace');root.querySelectorAll('[data-owner-tab]').forEach(b=>b.setAttribute('aria-selected',String(b===tab)));root.querySelectorAll('[data-owner-operation]').forEach(f=>f.hidden=f.dataset.ownerOperation!==tab.dataset.ownerTab);if(tab.dataset.ownerTab==='access'){const select=root.querySelector('[data-owner-products]');if(!select.dataset.ready)api('catalog').then(d=>{if(!select.isConnected)return;select._products=Object.entries({rt:d.templates,lt:d.linkTemplates,font:d.fonts,pal:d.palettes}).flatMap(([kind,list])=>list.map(x=>({...x,ref:kind+':'+x.id}))).sort((a,b)=>Number(b.updated_at||0)-Number(a.updated_at||0)||a.name.localeCompare(b.name,'fa'));select.dataset.ready='true';productOptions(root);}).catch(error=>{select.closest('form').querySelector('[role=status]').textContent=error.message;});}});
  document.addEventListener('input',e=>{if(e.target.matches('[data-owner-access-search]')){productOptions(e.target.closest('.owner-product-picker'));return;}if(!e.target.matches('[data-owner-product-search]'))return;const q=e.target.value.trim().toLowerCase();e.target.closest('form').querySelectorAll('[data-owner-product]').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q)&&!row.dataset.ownerProduct.includes(q));});
  document.addEventListener('change',e=>{if(e.target.matches('[data-owner-products]')){const selected=e.target._products?.find(x=>x.ref===e.target.value);e.target.closest('.owner-product-picker').querySelector('[data-product-selection]').textContent=selected?selected.name+' · '+(selected.admin_code||selected.ref):'یک محصول انتخاب کن';}});
  document.addEventListener('change',e=>{if(e.target.name==='show-password')e.target.closest('form').elements.password.type=e.target.checked?'text':'password';});
  document.addEventListener('input',e=>{const form=e.target.closest('[data-owner-operation],#owner-commerce-form');if(form&&!form.dataset.pending&&e.target.name&&e.target.name!=='show-password')delete form.dataset.requestId;});
  document.addEventListener('submit',async e=>{
   const form=e.target;if(!form.matches('[data-owner-operation],#owner-commerce-form'))return;e.preventDefault();if(form.dataset.pending)return;form.dataset.pending='true';const status=form.querySelector('[role=status]');status.textContent='در حال ثبت…';const fields=Object.fromEntries(new FormData(form)),requestId=form.dataset.requestId||(form.dataset.requestId=crypto.randomUUID()),controls=[...form.elements].filter(el=>!el.disabled);controls.forEach(el=>el.disabled=true);
   try{if(form.id==='owner-commerce-form'){const settings={...window.ownerCommerceSnapshot,rate:Number(fields.rate),imageFree:Number(fields.imageFree)*1024,imagePaid:Number(fields.imagePaid)*1024};await api('commerce',{settings,expectedSettings:window.ownerCommerceSnapshot,reason:fields.reason,confirmation:fields.confirmation,requestId});}
   else {const operation=form.dataset.ownerOperation,data={...fields};delete data.reason;delete data.confirmation;delete data['show-password'];if(operation==='subscription')data.days=Number(data.days);if(operation==='wallet')data.delta=Number(data.delta);if(operation==='access')data.enabled=fields.enabled==='true';if(operation==='page-quota'){data.limit=form.elements.unlimited.checked?null:Number(fields.limit);delete data.unlimited;}await api('users/'+form.dataset.user+'/owner-controls',{operation,data,reason:fields.reason,confirmation:fields.confirmation,requestId});if(operation==='password'&&form.dataset.user===ownerId()){location.assign('/login/');return;}}
   if(!form.isConnected)return;status.textContent='تغییر ذخیره و در سابقه ثبت شد';if(form.elements.password)form.elements.password.value='';if(form.closest('[hidden]')){status.textContent+='؛ برای دریافت اطلاعات تازه، صفحه را تازه کن.';return;}delete form.dataset.requestId;await reload();
   }catch(error){if(form.isConnected)status.textContent=error.message;}finally{delete form.dataset.pending;controls.forEach(el=>el.disabled=false);}
  });
 };
})();
